#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXN 10005
#define MAXM 100005

typedef struct {
    int to, next;
} Edge;

Edge edges[MAXM * 2];
int head[MAXN], edgeCnt;
int strength[MAXN];
int dp[MAXN][2];
int visited[MAXN];

void addEdge(int u, int v) {
    edges[edgeCnt].to = v;
    edges[edgeCnt].next = head[u];
    head[u] = edgeCnt++;
}

int max(int a, int b) {
    return a > b ? a : b;
}

void dfs(int u, int parent) {
    visited[u] = 1;
    dp[u][0] = 0;
    dp[u][1] = strength[u];

    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (v == parent) continue;
        dfs(v, u);
        dp[u][0] += max(dp[v][0], dp[v][1]);
        dp[u][1] += dp[v][0];
    }
}

int main() {
    int n, m;
    while (scanf("%d %d", &n, &m) == 2) {
        if (n == 0 && m == 0) break;

        // Initialize
        memset(head, -1, sizeof(head));
        memset(visited, 0, sizeof(visited));
        edgeCnt = 0;

        // Read strengths
        for (int i = 1; i <= n; i++) {
            scanf("%d", &strength[i]);
        }

        // Read edges
        for (int i = 0; i < m; i++) {
            int u, v;
            scanf("%d %d", &u, &v);
            addEdge(u, v);
            addEdge(v, u);
        }

        int totalStrength = 0;

        // Process each connected component
        for (int i = 1; i <= n; i++) {
            if (!visited[i]) {
                dfs(i, -1);
                totalStrength += max(dp[i][0], dp[i][1]);
            }
        }

        printf("%d\n", totalStrength);
    }
    return 0;
}

