#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int to;
    int next;
} Edge;

static int n;
static ll *w;
static int *head;
static Edge *edges;
static int edge_cnt;

static ll (*dp)[3];

static void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

static ll maxll(ll a, ll b) { return a > b ? a : b; }

/*
States for node u:
dp[u][0]: maximum strength in subtree of u, with u selected.
dp[u][1]: maximum strength in subtree of u, with u not selected, and no selected node
          among children of u (so parent of u may still be selected safely).
dp[u][2]: maximum strength in subtree of u, with u not selected, and at least one child
          of u selected.

Distance between any two selected nodes must be at least 3.
*/
static void dfs(int u, int p) {
    dp[u][0] = w[u];
    dp[u][1] = 0;
    dp[u][2] = -(1LL << 60);

    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        if (v == p) continue;
        dfs(v, u);

        ll n0 = -(1LL << 60), n1 = 0, n2 = -(1LL << 60);

        /* u selected => children and grandchildren cannot be selected
           so child must be in state 1 */
        n0 = dp[u][0] + dp[v][1];

        /* u not selected, no child selected yet => child cannot be selected */
        n1 = dp[u][1] + maxll(dp[v][1], dp[v][2]);

        /* u not selected, at least one child selected */
        ll best_no_select_v = maxll(dp[v][1], dp[v][2]);

        /* previous already had selected child, current child not selected */
        if (dp[u][2] > -(1LL << 59))
            n2 = maxll(n2, dp[u][2] + best_no_select_v);

        /* current child selected, previous children had none selected */
        n2 = maxll(n2, dp[u][1] + dp[v][0]);

        dp[u][0] = n0;
        dp[u][1] = n1;
        dp[u][2] = n2;
    }
}

int main(void) {
    while (scanf("%d", &n) == 1 && n) {
        w = (ll *)malloc((n + 1) * sizeof(ll));
        head = (int *)malloc((n + 1) * sizeof(int));
        edges = (Edge *)malloc((2 * (n - 1)) * sizeof(Edge));
        dp = (ll (*)[3])malloc((n + 1) * sizeof(ll[3]));

        for (int i = 1; i <= n; i++) scanf("%lld", &w[i]);
        for (int i = 1; i <= n; i++) head[i] = -1;
        edge_cnt = 0;

        for (int i = 0; i < n - 1; i++) {
            int u, v;
            scanf("%d %d", &u, &v);
            add_edge(u, v);
            add_edge(v, u);
        }

        dfs(1, 0);

        ll ans = maxll(dp[1][0], maxll(dp[1][1], dp[1][2]));
        printf("%lld\n", ans);

        free(w);
        free(head);
        free(edges);
        free(dp);
    }
    return 0;
}

