        for (int i = 0; i < n; i++) cin >> strength[i];

        vector<int> adj(n, 0);
        for (int i = 0; i < m; i++) {
            int u, v;
            cin >> u >> v;
            adj[u] |= (1 << v);
            adj[v] |= (1 << u);
        }

        int best = strength[0]; // at minimum, just your country

        for (int mask = 1; mask < (1 << n); mask++) {
            if (!(mask & 1)) continue; // must include country 0

            // Check if independent set
            bool valid = true;
            for (int i = 0; i < n && valid; i++) {
                if (mask & (1 << i)) {
                    if (adj[i] & mask) valid = false;
                }
            }

            if (valid) {
                int total = 0;
                for (int i = 0; i < n; i++)
                    if (mask & (1 << i)) total += strength[i];
                best = max(best, total);
            }
        }

        cout << best << "\n";
    }
    return 0;
}

