/*
This is the classic "maximum weight independent set on a tree".

Interpretation:
- Countries are vertices of a tree.
- If a country joins the alliance, neither its neighbors nor neighbors of those neighbors
  can join? The statement wording usually means:
  "You cannot form alliances with neighboring countries or with neighbors of allied countries"
  in the context of this known problem, it is exactly the independent set restriction:
  if a country is selected, its adjacent countries cannot be selected.
- We want the maximum total military strength of an alliance containing the capital/our own country?
  However the standard formulation asks for the maximum total over the whole tree.
  Since no special root/country is given in input, the intended solution is the tree DP maximum.

DP:
dp[u][1] = maximum strength in subtree of u if u is included
dp[u][0] = maximum strength in subtree of u if u is excluded

Transitions:
dp[u][1] = w[u] + sum(dp[v][0]) for children v
dp[u][0] = sum(max(dp[v][0], dp[v][1])) for children v

Input format assumed from the classic problem:
Multiple datasets.
Each dataset:
  n
  w1
  w2
  ...
  wn
  a b    (edge child-parent or undirected relation)
  ...
  0 0
And terminates by EOF.

This matches common tree alliance problems.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n) {
        vector<long long> w(n + 1);
        for (int i = 1; i <= n; ++i) cin >> w[i];

        vector<vector<int>> g(n + 1);
        vector<int> hasParent(n + 1, 0);

        while (true) {
            int a, b;
            cin >> a >> b;
            if (!cin) return 0;
            if (a == 0 && b == 0) break;
            g[a].push_back(b);
            g[b].push_back(a);
            hasParent[a] = 1; // useful for finding a root if input is directed-like
        }

        int root = 1;
        for (int i = 1; i <= n; ++i) {
            if (!hasParent[i]) {
                root = i;
                break;
            }
        }

        vector<array<long long, 2>> dp(n + 1, {0, 0});
        vector<int> parent(n + 1, 0);
        vector<int> order;
        order.reserve(n);

        // iterative DFS to avoid recursion depth issues
        stack<int> st;
        st.push(root);
        parent[root] = -1;

        while (!st.empty()) {
            int u = st.top();
            st.pop();
            order.push_back(u);
            for (int v : g[u]) {
                if (v == parent[u]) continue;
                parent[v] = u;
                st.push(v);
            }
        }

        for (int i = (int)order.size() - 1; i >= 0; --i) {
            int u = order[i];
            dp[u][1] = w[u];
            dp[u][0] = 0;
            for (int v : g[u]) {
                if (v == parent[u]) continue;
                dp[u][1] += dp[v][0];
                dp[u][0] += max(dp[v][0], dp[v][1]);
            }
        }

        cout << max(dp[root][0], dp[root][1]) << '\n';
    }

    return 0;
}

