        Arrays.fill(parent, -1);

        // BFS to build parent relationships
        Queue<Integer> queue = new LinkedList<>();
        queue.add(start);
        parent[start] = -2; // mark as visited

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : graph[u]) {
                if (parent[v] == -1) {
                    parent[v] = u;
                    queue.add(v);
                }
            }
        }

        // DP arrays: dp0 = not taking current node, dp1 = taking current node
        long[] dp0 = new long[n];
        long[] dp1 = new long[n];

        // Process nodes in reverse order (post-order)
        for (int u = n - 1; u >= 0; u--) {
            // Find actual node in BFS order
            int node = u; // We'll process based on discovery order

            // Actually, let's use a different approach - process leaves first
        }

        // Simpler approach: use recursion with memoization
        Long[][] memo = new Long[n][2];
        long result = dfs(start, -1, 1, memo); // must include start

        return String.valueOf(result);
    }

    static long dfs(int u, int parent, int take, Long[][] memo) {
        if (memo[u][take] != null) {
            return memo[u][take];
        }

        long result;
        if (take == 1) {
            // Take this node, cannot take children
            result = strength[u];
            for (int v : graph[u]) {
                if (v != parent) {
                    result += dfs(v, u, 0, memo);
                }
            }
        } else {
            // Don't take this node, can either take or not take children
            result = 0;
            for (int v : graph[u]) {
                if (v != parent) {
                    result += Math.max(dfs(v, u, 0, memo), dfs(v, u, 1, memo));
                }
            }
        }

        memo[u][take] = result;
        return result;
    }
}

