import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            if (n == 0) break;

            long[] w = new long[n + 1];
            for (int i = 1; i <= n; i++) w[i] = fs.nextInt();

            List<Integer>[] g = new ArrayList[n + 1];
            for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < n - 1; i++) {
                int a = fs.nextInt();
                int b = fs.nextInt();
                g[a].add(b);
                g[b].add(a);
            }

            long[][] dp = new long[n + 1][2];
            int[] parent = new int[n + 1];
            int[] order = new int[n];
            int idx = 0;

            int[] stack = new int[n];
            int top = 0;
            stack[top++] = 1;
            parent[1] = -1;

            while (top > 0) {
                int u = stack[--top];
                order[idx++] = u;
                for (int v : g[u]) {
                    if (v == parent[u]) continue;
                    parent[v] = u;
                    stack[top++] = v;
                }
            }

            for (int i = n - 1; i >= 0; i--) {
                int u = order[i];
                dp[u][1] = w[u];
                dp[u][0] = 0;
                for (int v : g[u]) {
                    if (v == parent[u]) continue;
                    dp[u][1] += dp[v][0];
                    dp[u][0] += Math.max(dp[v][0], dp[v][1]);
                }
            }

            out.append(Math.max(dp[1][0], dp[1][1])).append('\n');
        }

        System.out.print(out.toString());
    }
}
